using DG.Tweening;
using NaughtyAttributes;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class EffectInstance : ZoomableInstance
{
	[Header("Components")]
	[SerializeField]
	private Image effectImage;

	[SerializeField]
	private DOTweenAnimation effectImageDOTween;

	[SerializeField]
	private TextMeshProUGUI effectAmountText;

	[SerializeField]
	private DOTweenAnimation backgroundImageDOTween;

	private Effect effect;

	[ShowNonSerializedField]
	private int effectAmount;

	private GameObject effectOwner;

	public Effect Effect => effect;

	public int EffectAmount => effectAmount;

	public void Initialize(Effect effect, int effectAmount, GameObject effectOwner, GameObject source, bool effectFeedback, bool callEffectsCallbacks, bool gainingEffectVFXAndSFX, int renderLayer = -1)
	{
		StopBlinkingFeedback();
		ResetScale();
		this.effect = effect;
		this.effectAmount = effectAmount;
		ClampEffectAmount();
		this.effectOwner = effectOwner;
		SetImage(effect.EffectSprite);
		if (callEffectsCallbacks)
		{
			effect.InitializeVFX(effectOwner, gainingEffectVFXAndSFX);
			effect.Initialize(effectAmount, effectOwner, source);
		}
		if (GameScenesUtils.IsMainMenu())
		{
			effect.InitializeCompendium(effectAmount, effectOwner);
		}
		if (effect.HideEffectValue)
		{
			effectAmountText.enabled = false;
		}
		else
		{
			effectAmountText.enabled = true;
			effectAmountText.SetText(EffectAmountString());
			effectAmountText.color = GetEffectColor();
		}
		if (renderLayer == 10)
		{
			SetCameraEnum(CameraEnum.DicePreview);
		}
		else
		{
			SetCameraEnum(CameraEnum.MainCamera);
		}
	}

	private Color GetEffectColor()
	{
		if (!effect.EnableColorReference)
		{
			return effect.EffectColor;
		}
		return effect.EffectColorReference.Value;
	}

	public void SetImage(Sprite sprite)
	{
		effectImage.sprite = sprite;
		effectImage.color = (effect.ApplyColorToActionIcon ? GetEffectColor() : Color.white);
	}

	private void ClampEffectAmount()
	{
		if (effect.MaxEffectAmount > 0)
		{
			effectAmount = Mathf.Min(effectAmount, effect.MaxEffectAmount);
		}
	}

	public override void InitializeActionDescriptionPanel()
	{
		actionDescriptionPanel.Initialize(this, effectOwner);
	}

	private string EffectAmountString()
	{
		if (effectAmount <= -1 || effect.HideEffectValue)
		{
			return " ";
		}
		if (effectAmount >= EffectsValues.INFINITY)
		{
			return "∞";
		}
		return effectAmount.ToString();
	}

	public void IncreaseEffect(int amount, GameObject source, bool callEffectsCallbacks, bool gainingEffectVFXAndSFX)
	{
		if (effectAmount < EffectsValues.INFINITY)
		{
			effectAmount += amount;
		}
		ClampEffectAmount();
		if (callEffectsCallbacks)
		{
			effect.EffectIncreased(effectAmount, effectOwner, source);
			effect.EffectIncreasedSpawnVFX(effectOwner, gainingEffectVFXAndSFX);
		}
		UpdateAmount(activateFeedback: true, removeOnZero: false);
	}

	public void DecreaseEffect(int amount, bool activateFeedback = true, bool removeOnZero = true)
	{
		effectAmount -= amount;
		effectAmount = Mathf.Max(effectAmount, 0);
		if (effectAmount > 0)
		{
			effect.EffectDecreased(effectAmount, effectOwner);
		}
		UpdateAmount(activateFeedback, removeOnZero);
	}

	public void ActivateEffect(bool updateAmount = true)
	{
		if (updateAmount)
		{
			effectAmount = effect.ActivateEffect(effectAmount, effectOwner);
			UpdateAmount();
		}
		else
		{
			effect.ActivateEffect(effectAmount, effectOwner);
		}
	}

	public void ActivateEffectWithSource(GameObject source, bool updateAmount = true)
	{
		if (updateAmount)
		{
			effectAmount = effect.ActivateEffectWithSource(effectAmount, effectOwner, source);
			UpdateAmount();
		}
		else
		{
			effect.ActivateEffectWithSource(effectAmount, effectOwner, source);
		}
	}

	public void OptionalActivateEffect(bool updateAmount = true)
	{
		if (updateAmount)
		{
			effectAmount = effect.OptionalActivateEffect(effectAmount, effectOwner);
			UpdateAmount();
		}
		else
		{
			effect.OptionalActivateEffect(effectAmount, effectOwner);
		}
	}

	public void ActivateEffectWithSpecificDice(Dice dice, bool updateAmount = true)
	{
		if (updateAmount)
		{
			effectAmount = effect.ActivateEffectWithSpecificDice(effectAmount, effectOwner, dice);
			UpdateAmount();
		}
		else
		{
			effect.ActivateEffectWithSpecificDice(effectAmount, effectOwner, dice);
		}
	}

	public void ActivateEffectWithPurifyAmountAndSource(int purifyAmount, GameObject source, bool updateAmount = true)
	{
		if (updateAmount)
		{
			effectAmount = effect.ActivateEffectWithPurifyAmountAndSource(effectAmount, effectOwner, purifyAmount, source);
			UpdateAmount();
		}
		else
		{
			effect.ActivateEffectWithPurifyAmountAndSource(effectAmount, effectOwner, purifyAmount, source);
		}
	}

	public void ActivateEffectWithCorruptAmountAndSource(int purifyAmount, GameObject source, bool updateAmount = true)
	{
		if (updateAmount)
		{
			effectAmount = effect.ActivateEffectWithCorruptAmountAndSource(effectAmount, effectOwner, purifyAmount, source);
			UpdateAmount();
		}
		else
		{
			effect.ActivateEffectWithCorruptAmountAndSource(effectAmount, effectOwner, purifyAmount, source);
		}
	}

	private void UpdateAmount(bool activateFeedback = true, bool removeOnZero = true)
	{
		if (effect.name.Contains("DodgePurify"))
		{
			Debug.Log("DODGE PURIFY************" + EffectAmountString());
		}
		if (effectAmount == 0 && removeOnZero)
		{
			effectOwner.GetComponent<UnitEffects>().RemoveEffect(this, activateFeedback);
		}
		else
		{
			effectAmountText.SetText(EffectAmountString());
		}
	}

	public void PlayBlinkingFeedback()
	{
		effectImageDOTween.DOPlay();
		backgroundImageDOTween.DOPlay();
	}

	public void StopBlinkingFeedback(bool shouldForce = false)
	{
		if (shouldForce)
		{
			DOTween.Rewind(effectImageDOTween.gameObject);
			DOTween.Rewind(backgroundImageDOTween.gameObject);
		}
		else
		{
			backgroundImageDOTween.DORewind();
			effectImageDOTween.DORewind();
		}
	}

	public void SetEffectAmountTextFontSize(int size)
	{
		effectAmountText.fontSize = size;
	}
}
